CREATE SCHEMA IF NOT EXISTS {{SCHEMA}};
CREATE TABLE IF NOT EXISTS {{SCHEMA}}.CUSTOMERS (ID VARCHAR(20) PRIMARY KEY, NAME VARCHAR(200) NOT NULL, AVG_DAYS_LATE DECIMAL(10,2) NOT NULL, LATE_RATE DECIMAL(5,4) NOT NULL);
CREATE TABLE IF NOT EXISTS {{SCHEMA}}.INVOICES (ID VARCHAR(30) PRIMARY KEY, CUSTOMER_ID VARCHAR(20) NOT NULL, INVOICE_NUMBER VARCHAR(80) NOT NULL, INVOICE_DATE DATE NOT NULL, DUE_DATE DATE NOT NULL, AMOUNT DECIMAL(18,2) NOT NULL, STATUS VARCHAR(20) NOT NULL, SUPPLIER_ID VARCHAR(30) NOT NULL);
CREATE TABLE IF NOT EXISTS {{SCHEMA}}.PAYMENTS (ID VARCHAR(30) PRIMARY KEY, INVOICE_ID VARCHAR(30), PAYMENT_DATE DATE NOT NULL, AMOUNT DECIMAL(18,2) NOT NULL, REFERENCE VARCHAR(120) NOT NULL);
CREATE TABLE IF NOT EXISTS {{SCHEMA}}.AUDIT_EVENTS (ID VARCHAR(64) PRIMARY KEY, EVENT_TYPE VARCHAR(60) NOT NULL, CREATED_AT TIMESTAMP NOT NULL, DETAILS VARCHAR(2000) NOT NULL);
